 "content": "def transform(grid):
    H,W=len(grid),len(grid[0]); g=[r[:] for r in grid]
    # Solid 6 lines mark the boundaries; the upper-left tile is the pattern.
    rows=[r for r in range(H) if all(x==6 for x in grid[r])]
    cols=[c for c in range(W) if all(grid[r][c]==6 for r in range(H))]
    rb=[0]+[r+1 for r in rows]; re=rows+[H]
    cb=[0]+[c+1 for c in cols]; ce=cols+[W]
    sr0,sr1,sc0,sc1=rb[0],re[0],cb[0],ce[0]
    for r0,r1 in zip(rb,re):
      for c0,c1 in zip(cb,ce):
        if (r0,c0)==(sr0,sc0): continue
        for r in range(r0,r1):
          for c in range(c0,c1):
            rr=sr0+(r-r0); cc=sc0+(c-c0)
            if rr<sr1 and cc<sc1: g[r][c]=grid[rr][cc]
    return g
